arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -H "Content-Type: application/json" -d '{"token":"***","types":"public_channel,private_channel"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR', d); sys.exit()
for c in d['channels']:
    if 'launch' in c.get('name','').lower():
        print(c['id'], c['name'])
"

